class Solution:
    def splitPainting(self, segments: list[list[int]]) -> list[list[int]]:
        delta = {}
        for s, e, c in segments:
            delta[s] = delta.get(s, 0) + c
            delta[e] = delta.get(e, 0) - c
        keys = sorted(delta)
        ans = []
        cur = 0
        for i, x in enumerate(keys[:-1]):
            cur += delta[x]
            y = keys[i + 1]
            if cur:
                if ans and ans[-1][1] == x and ans[-1][2] == cur:
                    ans[-1][1] = y
                else:
                    ans.append([x, y, cur])
        return ans

